    let w1 = thread::spawn(move || {
        let ga = a1.lock().unwrap();
        let gb = b1.lock().unwrap();
        drop(gb);
        drop(ga);
    });

    let (a2, b2) = (Arc::clone(&mtx_a), Arc::clone(&mtx_b));
    let w2 = thread::spawn(move || {
        let gb = b2.lock().unwrap();
        let ga = a2.lock().unwrap();
        drop(ga);
        drop(gb);
    });

    w1.join().unwrap();
    w2.join().unwrap();
}

